Exec.Arguments:
        -NoProfile -NonInteractive -ExecutionPolicy Bypass -Command "
        $logFile = Join-Path $env:USERPROFILE '.azazael\scheduled_runs.log';
        $timestamp = Get-Date -Format 'yyyy-MM-dd HH:mm:ss';
        Add-Content -Path $logFile -Value \"[$timestamp] Starting Azazael cluster health check...\";
        $python = Get-Command python -ErrorAction SilentlyContinue;
        if (-not $python) { Add-Content -Path $logFile -Value \"[$timestamp] ERROR: python not found\"; exit 1 };
        $result = & python -c \"
import sys, os; sys.path.insert(0, os.path.join(os.environ['USERPROFILE'], 'azazael', 'src'))
from CORE.worm_registry import discover_worms, validate_registry
from CORE.WORMS.METACLUSTER import MetaCluster
discover_worms()
report = validate_registry()
print(f'{report[\\\"status\\\"].upper()}: {report[\\\"total_worms\\\"]} worms in {report[\\\"categories\\\"]} categories')
mc = MetaCluster()
mc.discover_all()
status = mc.get_status()
print(f'MetaCluster: {status.get(\\\"routing_paths\\\", \\\"?\\\")} paths, {status.get(\\\"cross_nature_routes\\\", \\\"?\\\")} routes')
\" 2>&1;
        Add-Content -Path $logFile -Value \"[$timestamp] $result\";
        Add-Content -Path $logFile -Value \"[$timestamp] Cluster check complete.\"
        "
